/// <summary>
/// Base class for PricingAttribute table <c>CustCollectionContact</c>.
/// </summary>
internal abstract class GUPPricingAttributeCustCollectionContact extends GUPAbstractPricingAttribute implements GUPIPricingAttribute
{

}

Method.Source:
    protected CustCollectionsContact getTableRecord(Common _pricingObject)
    {
        SalesTable             salesTable = _pricingObject as SalesTable;
        CustCollectionsContact custCollectionsContact;

        if (salesTable)
        {
            custCollectionsContact = CustCollectionsContact::find(salesTable.CustAccount);
        }

        return custCollectionsContact;
    }

    protected QueryBuildDataSource getQueryBuildDatasource(Query _query, Map _qbdsMap = null)
    {
        QueryBuildDataSource qbds, qbdsRoot;

        if (_qbdsMap && _qbdsMap.exists(tableStr(CustTable)))
        {
            qbdsRoot = _qbdsMap.lookup(tableStr(CustTable));
        }
        else
        {
            qbdsRoot = _query.addDataSource(tableNum(CustTable));

            if (_qbdsMap)
            {
                _qbdsMap.insert(tableStr(CustTable), qbdsRoot);
            }
        }

        if (_qbdsMap && _qbdsMap.exists(this.getQueryBuilderDatasourceIdentifier()))
        {
            qbds = _qbdsMap.lookup(this.getQueryBuilderDatasourceIdentifier());
        }
        else
        {
            qbds = qbdsRoot.addDataSource(tableNum(CustCollectionsContact));
            qbds.addLink(fieldNum(CustTable, AccountNum), fieldNum(CustCollectionsContact, AccountNum));
            qbds.joinMode(JoinMode::ExistsJoin);
            
            if (_qbdsMap)
            {
                _qbdsMap.insert(this.getQueryBuilderDatasourceIdentifier(), qbds);
            }
        }

        return qbds;
    }

    public Query buildPricingObjectQuery(Query _query, anytype _value, Map _qdbsMap = null)
    {
        QueryBuildDataSource qbds;

        qbds = this.getQueryBuildDatasource(_query, _qdbsMap);
        this.setQueryBuildDatasourceRange(qbds, _value);

        return _query;
    }
